// The Android icon resources the app and its manifest name exist (they are
// generated by tool/icons/generate_icons.py).
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:ledger_zero/services/notifications/notification_service.dart';

const _res = 'android/app/src/main/res';

void main() {
  test('the notification icon exists, is white and survives shrinking', () {
    final icon = File(
      '$_res/drawable/${NotificationService.statusBarIcon}.xml',
    );
    expect(icon.existsSync(), isTrue);
    // Status-bar icons are drawn by the system from the alpha channel: one
    // colour only.
    final colours = RegExp(
      r'fillColor="([^"]+)"',
    ).allMatches(icon.readAsStringSync()).map((m) => m.group(1)).toSet();
    expect(colours, {'#FFFFFFFF'});
    expect(
      File('$_res/raw/keep.xml').readAsStringSync(),
      contains('@drawable/${NotificationService.statusBarIcon}'),
    );
  });

  test('adaptive icon with a themed (monochrome) layer, round icon and '
      'legacy PNGs for every density', () {
    for (final name in ['ic_launcher', 'ic_launcher_round']) {
      final adaptive = File(
        '$_res/mipmap-anydpi-v26/$name.xml',
      ).readAsStringSync();
      expect(adaptive, contains('@drawable/ic_launcher_foreground'));
      expect(adaptive, contains('@drawable/ic_launcher_background'));
      expect(adaptive, contains('@drawable/ic_launcher_monochrome'));
      for (final density in ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']) {
        expect(File('$_res/mipmap-$density/$name.png').existsSync(), isTrue);
      }
    }
    final manifest = File(
      'android/app/src/main/AndroidManifest.xml',
    ).readAsStringSync();
    expect(manifest, contains('android:icon="@mipmap/ic_launcher"'));
    expect(manifest, contains('android:roundIcon="@mipmap/ic_launcher_round"'));
  });

  test('the launch screen shows the mark', () {
    for (final folder in ['drawable', 'drawable-v21']) {
      expect(
        File('$_res/$folder/launch_background.xml').readAsStringSync(),
        contains('@drawable/launch_logo'),
      );
    }
    expect(File('$_res/drawable/launch_logo.xml').existsSync(), isTrue);
  });
}
